package pro.erez.interstice.test;
import com.google.gson.*;import java.nio.file.*;import java.util.*;
import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.monster.Zombie;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.phys.Vec3;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.tick.ServerTickEvent;
import pro.erez.interstice.Interstice;import pro.erez.interstice.entity.CaveRiftSpiderEntity;import pro.erez.interstice.fauna.*;import pro.erez.interstice.worldgen.IslandWorld;
/** A disposable, loopback-only full-pack dedicated scene; never included in production JARs. */
@EventBusSubscriber(modid="interstice_geometry_fixture") public final class FaunaNetworkProbe{
 private static final boolean ACTIVE=Boolean.getBoolean("interstice.faunaNetworkProbe");private static ServerLevel level;private static VaultHunter hunter;private static CaveRiftSpiderEntity spider;private static Zombie prey,control;private static int bootTicks,ticks;private static boolean done,recorded;private static final Map<String,List<Double>> steps=new LinkedHashMap<>();private static final Map<String,Vec3> previous=new HashMap<>();private static final JsonArray series=new JsonArray();
 private static void require(boolean b,String why){if(!b)throw new IllegalStateException(why);}
 @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!ACTIVE||done)return;try{if(level!=null&&++bootTicks==40){var stale=new ArrayList<Entity>();for(var e:level.getAllEntities())if(e!=hunter&&e!=spider&&e!=prey&&e!=control&&e.hasCustomName()&&e.getCustomName().getString().startsWith("probe-"))stale.add(e);for(var e:stale)e.discard();Files.writeString(Path.of("fauna-network-ready.json"),"{\"ready\":true,\"real_v6\":true}");}if(event.getServer().getPlayerList().getPlayers().isEmpty())return;var player=event.getServer().getPlayerList().getPlayers().getFirst();
  if(level==null)prepare(event.getServer());if(ticks==0){hunter.setNoAi(false);spider.setNoAi(false);control.setNoAi(false);hunter.moveTo(3.5,70,22.5);spider.moveTo(3.5,70,29.5);control.moveTo(3.5,70,25.5);spider.setTarget(prey);}
  player.setGameMode(GameType.SURVIVAL);player.setNoGravity(true);player.setInvulnerable(false);
  player.teleportTo(level,hunter.getX()+8,70,22.5,Set.of(),-90,0);player.hasChangedDimension();prey.setPos(spider.getX()+15,70,29.5);if(ticks%10==0)control.getNavigation().moveTo(control.getX()+8,70,25.5,1);
  if(++ticks>80&&ticks<=440){var row=new JsonObject();row.addProperty("tick",ticks);row.addProperty("hunter_phase",hunter.phase().name());row.addProperty("hunter_has_player_target",hunter.getTarget()==player);for(var actor:List.of(hunter,spider,control)){String n=actor.getCustomName().getString();var at=actor.position();var old=previous.put(n,at);if(old!=null)steps.computeIfAbsent(n,k->new ArrayList<>()).add(at.subtract(old).horizontalDistance());var v=new JsonArray();v.add(at.x);v.add(at.y);v.add(at.z);row.add(n,v);}series.add(row);}
  if(ticks==440&&!recorded){var report=new JsonObject();report.addProperty("real_v6",true);report.addProperty("prepared_not_survival",true);report.addProperty("vanilla_control","Vanilla Zombie PathNavigation, refreshed ahead every 10 ticks");report.add("series",series);
   for(var entry:steps.entrySet()){var values=entry.getValue();var stats=stats(values);require(values.size()>=350&&stats.get("travelled").getAsDouble()>20,"No real progress "+entry.getKey()+" "+stats);if(!entry.getKey().equals("probe-vanilla"))require(stats.get("longest_idle_ticks").getAsInt()<=3,"Server movement paused "+entry.getKey()+" "+stats);report.add(entry.getKey(),stats);}
   require(steps.size()==3,"Missing motion actors");long chase=0;for(var s:series){var r=s.getAsJsonObject();if(r.get("hunter_phase").getAsString().equals("CHASE")&&r.get("hunter_has_player_target").getAsBoolean())chase++;}require(chase>=350,"Visible pursuit not maintained: "+chase);report.addProperty("chase_ticks",chase);report.addProperty("passed",true);Files.writeString(Path.of("fauna-network-server.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));recorded=true;
  }
 }catch(Throwable error){done=true;try{var r=new JsonObject();r.addProperty("passed",false);r.addProperty("error",error.toString());r.add("series",series);Files.writeString(Path.of("fauna-network-server.json"),new GsonBuilder().setPrettyPrinting().create().toJson(r));}catch(Exception ignored){}throw new IllegalStateException("Owned fauna TCP probe failed",error);}}
 private static void prepare(net.minecraft.server.MinecraftServer server)throws Exception{if(level!=null)return;require(Files.readString(Path.of(".owned-fauna-network-probe")).equals("disposable-localhost-only\n"),"Owned dedicated fixture required");level=server.getLevel(IslandWorld.TENSION_WORLD);require(StrongRealmFauna.isV6(level),"Real V6 required");level.getGameRules().getRule(GameRules.RULE_DOMOBSPAWNING).set(false,server);
   for(int x=-16;x<=176;x+=16)for(int z=16;z<=48;z+=16)level.getChunkAt(new BlockPos(x,70,z));for(int x=0;x<=170;x++)for(int z=18;z<=34;z++){level.setBlock(new BlockPos(x,69,z),Blocks.STONE.defaultBlockState(),3);for(int y=70;y<=76;y++)level.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}
   for(int x=0;x<=170;x+=4)for(int z=20;z<=32;z+=4)level.setBlock(new BlockPos(x,75,z),Blocks.GLOWSTONE.defaultBlockState(),3);
   hunter=StrongRealmFauna.VAULT_HUNTER.get().create(level);hunter.moveTo(3.5,70,22.5);add(hunter,"probe-hunter");spider=Interstice.CAVE_RIFT_SPIDER.get().create(level);spider.setVariant(CaveRiftSpiderEntity.Variant.SPITTER);spider.moveTo(3.5,70,29.5);add(spider,"probe-spitter");prey=new Zombie(EntityType.ZOMBIE,level);prey.setNoAi(true);prey.setNoGravity(true);prey.moveTo(18.5,70,29.5);add(prey,"probe-prey");spider.setTarget(prey);control=new Zombie(EntityType.ZOMBIE,level);control.moveTo(3.5,70,25.5);add(control,"probe-vanilla");
   hunter.setNoAi(true);spider.setNoAi(true);control.setNoAi(true);
 }
 @SubscribeEvent public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent event){if(!ACTIVE)return;try{prepare(event.getServer());}catch(Exception error){throw new IllegalStateException("Owned arena setup failed",error);}}
 static JsonObject stats(List<Double> values){var r=new JsonObject();double sum=values.stream().mapToDouble(Double::doubleValue).sum(),mean=sum/values.size();int longest=0,streak=0;for(double v:values){streak=v<.005?streak+1:0;longest=Math.max(longest,streak);}r.addProperty("samples",values.size());r.addProperty("travelled",sum);r.addProperty("mean",mean);r.addProperty("max",values.stream().mapToDouble(Double::doubleValue).max().orElse(0));r.addProperty("longest_idle_ticks",longest);return r;}
 static void add(Mob e,String name){e.setPersistenceRequired();e.setInvulnerable(true);e.setCustomName(Component.literal(name));require(level.addFreshEntity(e),"Could not add "+name);}
}
